use std::collections::{BTreeSet, HashMap};
use std::fmt::Write;

use heck::{ToSnakeCase, ToUpperCamelCase};
use prost_reflect::{DescriptorPool, FieldDescriptor, Kind, MessageDescriptor, Value};

const PAIR_EXTENSION: &str = "bolt.options.v1.pair";
const HEADER: &str =
    "// @generated by protoc-gen-bolt from bolt.options.v1 options. DO NOT EDIT.\n";

/// Well-known wrappers that prost maps to `Option<scalar>` rather than a struct.
const WRAPPERS: &[&str] = &[
    "google.protobuf.DoubleValue",
    "google.protobuf.FloatValue",
    "google.protobuf.Int64Value",
    "google.protobuf.UInt64Value",
    "google.protobuf.Int32Value",
    "google.protobuf.UInt32Value",
    "google.protobuf.BoolValue",
    "google.protobuf.StringValue",
    "google.protobuf.BytesValue",
];

pub fn generate(pool: &DescriptorPool, files: &[String]) -> Result<String, String> {
    let mut out = String::from(HEADER);
    let Some(pair_ext) = pool.get_extension_by_name(PAIR_EXTENSION) else {
        return Ok(out);
    };
    let files: BTreeSet<&str> = files.iter().map(String::as_str).collect();

    let mut errors = Vec::new();
    for message in pool.all_messages() {
        if !files.contains(message.parent_file().name()) {
            continue;
        }
        let options = message.options();
        if !options.has_extension(&pair_ext) {
            continue;
        }
        match render_pair(&message, &options.get_extension(&pair_ext)) {
            Ok(code) => out.push_str(&code),
            Err(e) => errors.push(format!(
                "{}: {}: {e}",
                message.parent_file().name(),
                message.full_name()
            )),
        }
    }

    if errors.is_empty() {
        Ok(out)
    } else {
        Err(errors.join("\n"))
    }
}

fn pair_paths(spec: &Value) -> Result<(String, String), String> {
    let path = |name: &str| match spec.as_message().map(|m| m.get_field_by_name(name)) {
        Some(Some(value)) => value.as_str().unwrap_or_default().to_owned(),
        _ => String::new(),
    };
    let (base, quote) = (path("base"), path("quote"));
    if base.is_empty() || quote.is_empty() {
        return Err("(bolt.options.v1.pair) needs both base and quote".to_owned());
    }
    Ok((base, quote))
}

fn render_pair(message: &MessageDescriptor, spec: &Value) -> Result<String, String> {
    let (base, quote) = pair_paths(spec)?;

    let mut body = Body::default();
    let (base_ty, base_expr) = body
        .resolve(message, &base)
        .map_err(|e| format!("base path `{base}`: {e}"))?;
    let (quote_ty, quote_expr) = body
        .resolve(message, &quote)
        .map_err(|e| format!("quote path `{quote}`: {e}"))?;

    let ty = format!("({base_ty}, {quote_ty})");
    let expr = format!("({base_expr}, {quote_expr})");
    let (ty, expr) = if body.fallible {
        (
            format!("::core::option::Option<{ty}>"),
            format!("Some({expr})"),
        )
    } else {
        (ty, expr)
    };

    let mut code = String::new();
    writeln!(code, "\nimpl {} {{", rust_path(message)).unwrap();
    writeln!(
        code,
        "    /// (base, quote) from `(bolt.options.v1.pair)`: `{base}`, `{quote}`."
    )
    .unwrap();
    if body.fallible {
        writeln!(
            code,
            "    /// `None` when a message field or `optional` field on either path is unset."
        )
        .unwrap();
    }
    writeln!(code, "    pub fn pair(&self) -> {ty} {{").unwrap();
    for line in &body.lets {
        writeln!(code, "        {line}").unwrap();
    }
    writeln!(code, "        {expr}").unwrap();
    writeln!(code, "    }}\n}}").unwrap();
    Ok(code)
}

/// Accumulates the `let` bindings shared by both paths of a pair, so a message field
/// used by both (`instrument.base`, `instrument.quote`) is unwrapped once.
#[derive(Default)]
struct Body {
    lets: Vec<String>,
    bindings: HashMap<String, String>,
    fallible: bool,
}

impl Body {
    fn resolve(
        &mut self,
        root: &MessageDescriptor,
        path: &str,
    ) -> Result<(String, String), String> {
        let segments: Vec<&str> = path.split('.').collect();
        let (leaf, hops) = segments
            .split_last()
            .expect("split yields at least one segment");

        let mut message = root.clone();
        let mut expr = "self".to_owned();
        for (depth, segment) in hops.iter().enumerate() {
            let field = lookup(&message, segment)?;
            let Kind::Message(next) = field.kind() else {
                return Err(format!(
                    "`{segment}` is not a message field, so the path can't go through it"
                ));
            };
            if WRAPPERS.contains(&next.full_name()) {
                return Err(format!(
                    "`{segment}` is a `{}`, which prost maps to an `Option` of a scalar, not a struct",
                    next.full_name()
                ));
            }
            let prefix = segments[..=depth].join(".");
            expr = match self.bindings.get(&prefix) {
                Some(var) => var.clone(),
                None => {
                    let var = format!("m{}", self.bindings.len());
                    self.lets.push(format!(
                        "let {var} = {expr}.{}.as_ref()?;",
                        field_ident(&field)
                    ));
                    self.bindings.insert(prefix, var.clone());
                    self.fallible = true;
                    var
                }
            };
            message = next;
        }

        let field = lookup(&message, leaf)?;
        let access = format!("{expr}.{}", field_ident(&field));
        let optional = field.supports_presence();
        let (ty, by_ref) = match field.kind() {
            Kind::String => ("&str", true),
            Kind::Bytes => ("&[u8]", true),
            Kind::Double => ("f64", false),
            Kind::Float => ("f32", false),
            Kind::Int32 | Kind::Sint32 | Kind::Sfixed32 => ("i32", false),
            Kind::Int64 | Kind::Sint64 | Kind::Sfixed64 => ("i64", false),
            Kind::Uint32 | Kind::Fixed32 => ("u32", false),
            Kind::Uint64 | Kind::Fixed64 => ("u64", false),
            Kind::Bool => ("bool", false),
            Kind::Message(_) | Kind::Enum(_) => {
                return Err(format!(
                    "`{leaf}` must be a scalar field (string, bytes, integer, bool or float)"
                ));
            }
        };
        let expr = match (by_ref, optional) {
            (true, true) => format!("{access}.as_deref()?"),
            (true, false) => format!("&*{access}"),
            (false, true) => format!("{access}?"),
            (false, false) => access,
        };
        self.fallible |= optional;
        Ok((ty.to_owned(), expr))
    }
}

fn lookup(message: &MessageDescriptor, name: &str) -> Result<FieldDescriptor, String> {
    let field = message
        .get_field_by_name(name)
        .ok_or_else(|| format!("`{}` has no field `{name}`", message.full_name()))?;
    if field.is_list() || field.is_map() {
        return Err(format!(
            "`{name}` is repeated or a map; a pair side needs a single value"
        ));
    }
    if field
        .containing_oneof()
        .is_some_and(|oneof| !oneof.is_synthetic())
    {
        return Err(format!(
            "`{name}` is in a oneof, which prost models as an enum"
        ));
    }
    Ok(field)
}

fn rust_path(message: &MessageDescriptor) -> String {
    let mut segments: Vec<String> = message
        .package_name()
        .split('.')
        .map(|s| sanitize_identifier(s.to_snake_case()))
        .collect();
    let mut parents = Vec::new();
    let mut parent = message.parent_message();
    while let Some(p) = parent {
        parents.push(sanitize_identifier(p.name().to_snake_case()));
        parent = p.parent_message();
    }
    segments.extend(parents.into_iter().rev());
    segments.push(sanitize_identifier(message.name().to_upper_camel_case()));
    format!("crate::{}", segments.join("::"))
}

fn field_ident(field: &FieldDescriptor) -> String {
    sanitize_identifier(field.name().to_snake_case())
}

/// Mirrors prost-build's `ident::sanitize_identifier`, so generated paths match prost's.
fn sanitize_identifier(ident: String) -> String {
    match ident.as_str() {
        "as" | "break" | "const" | "continue" | "else" | "enum" | "false" | "fn" | "for" | "if"
        | "impl" | "in" | "let" | "loop" | "match" | "mod" | "move" | "mut" | "pub" | "ref"
        | "return" | "static" | "struct" | "trait" | "true" | "type" | "unsafe" | "use"
        | "where" | "while" | "dyn" | "abstract" | "become" | "box" | "do" | "final" | "macro"
        | "override" | "priv" | "typeof" | "unsized" | "virtual" | "yield" | "async" | "await"
        | "try" | "gen" => format!("r#{ident}"),
        "_" | "super" | "self" | "Self" | "extern" | "crate" => ident + "_",
        s if s.starts_with(|c: char| c.is_numeric()) => format!("_{ident}"),
        _ => ident,
    }
}
